exec('\nfrom __future__ import annotations\n\nimport datetime as dt\nimport time\nimport warnings\nfrom pathlib import Path\nfrom urllib.parse import quote_plus\nimport xml.etree.ElementTree as ET\n\nimport numpy as np\nimport pandas as pd\nimport plotly.graph_objects as go\nimport requests\nimport streamlit as st\nimport yfinance as yf\n\nfrom sklearn.linear_model import Ridge, ElasticNet, HuberRegressor, Lasso\nfrom sklearn.ensemble import ExtraTreesRegressor, RandomForestRegressor, GradientBoostingRegressor, VotingRegressor, HistGradientBoostingRegressor\nfrom sklearn.metrics import mean_squared_error\n\nwarnings.filterwarnings("ignore")\nROOT = Path(__file__).resolve().parents[1]\n\n# =============================================================================\n# PURPOSE\n# =============================================================================\n\nAPP_PURPOSE = """\nThis cockpit answers a simple path:\n\n1. **What is the instrument?** Company, ETF, future, index or macro proxy.\n2. **What is the tape?** Price, volume, dollar volume, returns, volatility, alpha and beta.\n3. **What is driving it?** Macro, material chain, own price action or news.\n4. **So what?** Tailwind, headwind or mixed for this specific instrument.\n5. **Can we trust the model?** Validated signal, horizon, invalidation triggers.\n"""\n\n# =============================================================================\n# STATIC MAPS\n# =============================================================================\n\nCORE_ASSETS = {\n    "SPY": ("SPDR S&P 500 ETF", "ETF", "US large-cap benchmark", "broad risk appetite"),\n    "RSP": ("S&P 500 Equal Weight ETF", "ETF", "US breadth", "equal-weight market breadth"),\n    "IWM": ("Russell 2000 ETF", "ETF", "US small caps", "rates, credit, risk appetite"),\n    "XME": ("SPDR Metals & Mining ETF", "ETF", "Mining and metals", "steel, copper, energy, China demand"),\n    "COPX": ("Global X Copper Miners ETF", "ETF", "Copper miners", "copper, USD, energy, China demand"),\n    "ITA": ("iShares U.S. Aerospace & Defense ETF", "ETF", "Aerospace and defense", "titanium, aluminum, nickel, defense procurement"),\n    "XAR": ("SPDR Aerospace & Defense ETF", "ETF", "Aerospace supply chain", "titanium, aluminum, nickel, energy"),\n    "PRNT": ("3D Printing ETF", "ETF", "Additive manufacturing", "titanium powder, nickel, aluminum, LPBF, EBM, HIP"),\n    "SOXX": ("iShares Semiconductor ETF", "ETF", "Semiconductors", "rare earths, Taiwan, electronics"),\n    "GLD": ("SPDR Gold Shares", "ETF", "Gold", "safe haven, real rates, geopolitical stress"),\n    "SLV": ("iShares Silver Trust", "ETF", "Silver", "solar, electronics, safe haven"),\n    "USO": ("United States Oil Fund", "ETF", "Oil", "fuel, inflation, Middle East"),\n    "UNG": ("United States Natural Gas Fund", "ETF", "Natural gas", "LNG, process energy, power prices"),\n    "URA": ("Global X Uranium ETF", "ETF", "Uranium", "nuclear fuel, energy security"),\n    "LIT": ("Global X Lithium & Battery Tech ETF", "ETF", "Battery materials", "lithium, nickel, cobalt, graphite"),\n    "REMX": ("VanEck Rare Earth/Strategic Metals ETF", "ETF", "Rare earths", "magnets, defense electronics, export controls"),\n    "SLX": ("VanEck Steel ETF", "ETF", "Steel", "iron ore, coking coal, steel margins"),\n}\n\nMAJOR_INDICES = {\n    "S&P 500": "^GSPC", "Nasdaq 100": "^NDX", "Dow Jones": "^DJI",\n    "Russell 2000": "^RUT", "Russell 1000": "^RUI", "Russell 3000": "^RUA",\n    "NYSE Composite": "^NYA", "S&P Equal Weight ETF": "RSP", "Russell 2000 ETF": "IWM",\n    "US Industrials": "XLI", "US Materials": "XLB", "US Energy": "XLE", "US Technology": "XLK",\n    "Euro Stoxx 50": "^STOXX50E", "DAX Germany": "^GDAXI", "CAC 40 France": "^FCHI",\n    "FTSE 100 UK": "^FTSE", "FTSE MIB Italy": "FTSEMIB.MI", "Europe ETF": "VGK",\n    "Nikkei 225 Japan": "^N225", "TOPIX Japan": "^TOPX", "Hang Seng": "^HSI",\n    "CSI 300 China": "000300.SS", "Shanghai Composite": "000001.SS", "Taiwan Weighted": "^TWII",\n    "KOSPI South Korea": "^KS11", "Nifty 50 India": "^NSEI", "MSCI World proxy": "URTH",\n    "Emerging Markets": "EEM", "Global Industrials": "EXI", "Global Materials": "MXI",\n}\n\nMACRO_PROXIES = {\n    "VIX volatility": "^VIX",\n    "US dollar index": "DX-Y.NYB",\n    "US 10Y yield": "^TNX",\n    "US 13-week yield": "^IRX",\n    "High-yield credit": "HYG",\n    "Investment-grade credit": "LQD",\n    "EUR/USD": "EURUSD=X",\n    "USD/CNY": "CNY=X",\n    "USD/JPY": "JPY=X",\n    "Gold": "GC=F",\n    "Silver": "SI=F",\n    "WTI oil": "CL=F",\n    "Brent oil": "BZ=F",\n    "Natural gas": "NG=F",\n    "Copper": "HG=F",\n    "Semiconductors": "SOXX",\n    "Freight proxy": "BDRY",\n}\n\nFUTURES = {\n    "WTI crude oil": "CL=F", "Brent crude oil": "BZ=F", "Natural gas": "NG=F",\n    "Copper": "HG=F", "Gold": "GC=F", "Silver": "SI=F", "Platinum": "PL=F",\n    "Palladium": "PA=F", "Iron ore proxy": "TIO=F", "US dollar index": "DX-Y.NYB",\n    "VIX volatility": "^VIX", "US 10Y yield": "^TNX", "Gold ETF": "GLD",\n    "Silver ETF": "SLV", "Oil ETF": "USO", "Natural gas ETF": "UNG",\n    "Uranium ETF": "URA", "Rare earth ETF": "REMX", "Lithium/battery ETF": "LIT",\n    "Steel ETF": "SLX", "Copper miners ETF": "COPX",\n}\n\nCHAIN_MAP = {\n    "Copper": {\n        "proxy": ["HG=F", "CPER", "COPX"],\n        "keywords": ["copper", "electrification", "grid", "wire", "motor"],\n        "path": "ore → concentrate → cathode → wire/rod → grids, motors, electronics",\n        "producer_effect": "usually revenue-positive for copper miners when demand-driven",\n        "user_effect": "usually cost pressure for manufacturers using copper-heavy components",\n    },\n    "Aluminum": {\n        "proxy": ["ALI=F", "AA"],\n        "keywords": ["aluminum", "aluminium", "aerospace", "auto", "smelter"],\n        "path": "bauxite → alumina → smelting → sheet/plate → aircraft, autos, packaging",\n        "producer_effect": "can support aluminum producers if demand-driven",\n        "user_effect": "cost pressure for aircraft, auto and packaging users",\n    },\n    "Titanium / AM powder": {\n        "proxy": ["ATI", "TROX", "CRS"],\n        "keywords": ["titanium", "powder", "additive", "lpbf", "ebm", "hip", "aerospace"],\n        "path": "ore → sponge → ingot/bar → powder/wire → LPBF, EBM, DED, HIP parts",\n        "producer_effect": "supports specialty alloy and powder suppliers if demand is strong",\n        "user_effect": "cost and availability risk for AM, aerospace and medical users",\n    },\n    "Nickel / superalloys": {\n        "proxy": ["JJN", "VALE", "NILSY"],\n        "keywords": ["nickel", "superalloy", "engine", "stainless", "battery"],\n        "path": "ore → refined nickel → stainless/superalloys/cathodes → turbines and batteries",\n        "producer_effect": "can support nickel miners/refiners",\n        "user_effect": "cost pressure for superalloys, engines, stainless and battery cathodes",\n    },\n    "Rare earth magnets": {\n        "proxy": ["REMX", "MP", "LYC.AX"],\n        "keywords": ["rare earth", "neodymium", "dysprosium", "magnet", "defense", "semiconductor"],\n        "path": "ore → separation → NdPr/Dy/Tb oxides → magnets → EV motors, defense electronics",\n        "producer_effect": "can support rare-earth miners/processors",\n        "user_effect": "supply-chain risk for magnets, defense electronics, EV motors and semis",\n    },\n    "Steel / PM inputs": {\n        "proxy": ["SLX", "TIO=F", "HCC", "NUE", "MT"],\n        "keywords": ["steel", "iron ore", "coking coal", "powder metallurgy", "machinery", "construction"],\n        "path": "iron ore/scrap/coal → steel → sheet/bar/powder → machinery, autos, PM parts",\n        "producer_effect": "can support steel names when demand is strong",\n        "user_effect": "cost pressure for machinery, autos, construction and PM input chains",\n    },\n    "Battery materials": {\n        "proxy": ["LIT", "ALB", "SQM", "NMG"],\n        "keywords": ["lithium", "battery", "ev", "cobalt", "graphite", "cathode", "anode"],\n        "path": "lithium/nickel/cobalt/graphite → cathode/anode → cells → EV and storage",\n        "producer_effect": "can support battery-material producers",\n        "user_effect": "margin pressure for EV and battery manufacturers if input-driven",\n    },\n    "Uranium / nuclear": {\n        "proxy": ["URA", "URNM", "CCJ"],\n        "keywords": ["uranium", "nuclear", "enrichment", "fuel"],\n        "path": "mine → conversion → enrichment → fuel fabrication → nuclear power",\n        "producer_effect": "supports uranium producers when contract/spot pricing improves",\n        "user_effect": "energy-security signal more than a direct manufacturing input",\n    },\n    "Energy / process cost": {\n        "proxy": ["CL=F", "BZ=F", "NG=F", "USO", "UNG"],\n        "keywords": ["oil", "gas", "fuel", "lng", "power", "chemicals", "heat treatment", "atomization"],\n        "path": "oil/gas/power → fuel/logistics/process heat → smelting, HIP, atomization, chemicals",\n        "producer_effect": "supports energy producers when demand-driven",\n        "user_effect": "cost pressure for manufacturers, smelters, chemical plants and AM processing",\n    },\n    "Gold / silver hedge": {\n        "proxy": ["GC=F", "GLD", "SI=F", "SLV"],\n        "keywords": ["gold", "silver", "safe haven", "solar", "electronics", "bullion"],\n        "path": "precious metals → hedge and industrial demand → ETFs, miners, electronics",\n        "producer_effect": "supports precious-metal exposure",\n        "user_effect": "gold is a stress hedge; silver is also an industrial input",\n    },\n}\n\nSCENARIO_PRESETS = {\n    "No shock selected": {},\n    "Risk-off: rates + USD + VIX up": {"rates": 1.25, "usd": 1.25, "vix": 1.5, "credit": 1.0},\n    "Energy shock: oil/gas/process cost up": {"energy": 1.5, "freight": .75, "usd": .25},\n    "China slowdown": {"china": -1.5, "copper": -1.0, "steel": -1.0, "battery": -.5},\n    "China restocking / industrial rebound": {"china": 1.5, "copper": 1.0, "steel": .75, "battery": .5},\n    "Europe industrial squeeze": {"eu": -1.25, "energy": 1.0, "rates": .75, "usd": .5},\n    "Defense and aerospace upcycle": {"defense": 1.5, "aerospace": 1.25, "titanium": .75, "rare_earth": .5},\n    "AM/PM input-cost squeeze": {"ampm": 1.5, "energy": 1.0, "nickel": .75, "titanium": 1.0},\n    "Rare-earth export-control shock": {"policy": 1.5, "rare_earth": 1.5, "china": -.5, "defense": .75},\n    "Gold/silver hedge bid": {"precious": 1.5, "vix": 1.0, "usd": -.25, "rates": -.5},\n    "Small-cap reflation": {"rates": -1.0, "credit": -1.0, "vix": -1.0, "china": .5},\n}\n\nSCENARIO_LABELS = {\n    "copper": "Copper/electrification", "aluminum": "Aluminum/lightweighting", "titanium": "Titanium/aerospace powder",\n    "nickel": "Nickel/superalloys", "steel": "Steel/PM inputs", "battery": "Battery materials",\n    "rare_earth": "Rare earth/policy", "uranium": "Uranium/nuclear", "precious": "Gold/silver hedge",\n    "energy": "Oil/gas/process cost", "usd": "US dollar", "rates": "Rates/yields", "vix": "VIX/risk-off",\n    "credit": "Credit stress", "china": "China demand", "eu": "Europe industrial", "defense": "Defense spending",\n    "aerospace": "Aerospace backlog", "semis": "Semiconductor cycle", "ampm": "AM/powder metallurgy",\n    "freight": "Shipping/freight", "policy": "Sanctions/export controls",\n}\n\n# =============================================================================\n# BASIC HELPERS\n# =============================================================================\n\ndef load_companies():\n    for p in [ROOT / "data/global_manufacturing_universe_extended.csv", ROOT / "data/manufacturing_company_universe.csv"]:\n        try:\n            if p.exists():\n                df = pd.read_csv(p)\n                for c in ["ticker", "company", "country", "region", "industry_group", "material_link", "why_relevant"]:\n                    if c not in df.columns:\n                        df[c] = ""\n                if not df.empty:\n                    return df.drop_duplicates("ticker")\n        except Exception:\n            pass\n    return pd.DataFrame(columns=["ticker", "company", "country", "region", "industry_group", "material_link", "why_relevant"])\n\nCOMPANIES = load_companies()\n\ndef compatible_period(interval, period):\n    if interval == "1m":\n        return period if period in ["1d", "5d"] else "5d"\n    if interval in ["5m", "15m", "30m", "60m"]:\n        return period if period in ["1d", "5d", "1mo", "3mo", "6mo"] else "60d"\n    return period\n\ndef delta_for(interval, bars):\n    if interval.endswith("m"):\n        return dt.timedelta(minutes=int(interval[:-1]) * bars)\n    return dt.timedelta(days=bars)\n\ndef fmt_num(x):\n    if x is None or pd.isna(x):\n        return ""\n    try:\n        x = float(x)\n    except Exception:\n        return str(x)\n    if abs(x) >= 1e12: return f"{x/1e12:.2f}T"\n    if abs(x) >= 1e9: return f"{x/1e9:.2f}B"\n    if abs(x) >= 1e6: return f"{x/1e6:.2f}M"\n    if abs(x) >= 1e3: return f"{x/1e3:.2f}K"\n    return f"{x:,.2f}"\n\ndef fmt_pct(x):\n    return "" if pd.isna(x) else f"{x*100:.2f}%"\n\ndef zscore(s, w):\n    w = max(3, int(w))\n    m = s.rolling(w, min_periods=max(3, w // 3)).mean()\n    sd = s.rolling(w, min_periods=max(3, w // 3)).std()\n    return ((s - m) / sd).replace([np.inf, -np.inf], np.nan)\n\ndef asset_profile(ticker):\n    if ticker in CORE_ASSETS:\n        name, typ, group, link = CORE_ASSETS[ticker]\n        return name, typ, group, link, "", ""\n    row = COMPANIES[COMPANIES["ticker"].astype(str) == ticker]\n    if not row.empty:\n        r = row.iloc[0]\n        return str(r["company"]), "equity", str(r["industry_group"]), str(r["material_link"]), str(r["country"]), str(r["region"])\n    for name, t in {**FUTURES, **MAJOR_INDICES, **MACRO_PROXIES}.items():\n        if t == ticker:\n            typ = "index" if ticker in MAJOR_INDICES.values() or ticker.startswith("^") else "future/macro"\n            return name, typ, name, name, "", ""\n    return ticker, "instrument", "unclassified", ticker, "", ""\n\ndef relevant_chains(ticker):\n    name, typ, group, link, country, region = asset_profile(ticker)\n    text = f"{ticker} {name} {typ} {group} {link} {country} {region}".lower()\n    hits = []\n    for chain, spec in CHAIN_MAP.items():\n        if chain.lower().split()[0] in text or any(k.lower() in text for k in spec["keywords"]):\n            hits.append(chain)\n    if not hits:\n        if any(w in text for w in ["aerospace", "defense", "engine"]):\n            hits = ["Titanium / AM powder", "Aluminum", "Nickel / superalloys", "Rare earth magnets", "Energy / process cost"]\n        elif any(w in text for w in ["mining", "metal", "copper"]):\n            hits = ["Copper", "Steel / PM inputs", "Energy / process cost", "Gold / silver hedge"]\n        elif "semiconductor" in text or "electronics" in text:\n            hits = ["Rare earth magnets", "Copper", "Gold / silver hedge", "Energy / process cost"]\n        elif "battery" in text or "ev" in text:\n            hits = ["Battery materials", "Nickel / superalloys", "Rare earth magnets"]\n        elif "europe etf" in text or ticker == "VGK":\n            hits = ["Energy / process cost", "Steel / PM inputs", "Copper"]\n        elif "gold" in text or "silver" in text:\n            hits = ["Gold / silver hedge"]\n        elif "oil" in text or "gas" in text or "energy" in text:\n            hits = ["Energy / process cost"]\n    return [h for h in hits if h in CHAIN_MAP]\n\ndef chain_effect_for_focus(chain, score, focus):\n    name, typ, group, link, country, region = asset_profile(focus)\n    text = f"{typ} {group} {link}".lower()\n    spec = CHAIN_MAP.get(chain, {})\n    if any(w in text for w in ["mining", "copper", "steel", "rare", "uranium", "gold", "silver", "energy", "oil", "gas", "aluminum"]):\n        effect = spec.get("producer_effect", "may support producer economics")\n        tilt = "potential tailwind" if score > 0.75 else "potential headwind" if score < -0.75 else "mixed"\n    else:\n        effect = spec.get("user_effect", "may affect cost, supply or demand")\n        tilt = "potential headwind" if score > 0.75 else "potential relief" if score < -0.75 else "mixed"\n    return tilt, effect\n\ndef readable_signal_name(feature):\n    return (feature.replace("macro:", "")\n                   .replace("chain:", "")\n                   .replace("asset:", "")\n                   .replace("basket:", ""))\n\n# =============================================================================\n# DATA\n# =============================================================================\n\n@st.cache_data(ttl=45, show_spinner=False)\ndef download_ohlcv(tickers, period, interval):\n    tickers = sorted(set([t for t in tickers if isinstance(t, str) and t.strip()]))\n    if not tickers:\n        return pd.DataFrame(), pd.DataFrame(), []\n    raw = yf.download(tickers, period=period, interval=interval, auto_adjust=False, progress=False, threads=True)\n    if raw.empty:\n        return pd.DataFrame(), pd.DataFrame(), tickers\n    if isinstance(raw.columns, pd.MultiIndex):\n        close = raw["Close"].copy() if "Close" in raw.columns.get_level_values(0) else pd.DataFrame()\n        volume = raw["Volume"].copy() if "Volume" in raw.columns.get_level_values(0) else pd.DataFrame(index=close.index)\n    else:\n        close = raw[["Close"]].copy()\n        volume = raw[["Volume"]].copy() if "Volume" in raw.columns else pd.DataFrame(index=close.index)\n        if len(tickers) == 1:\n            close.columns = tickers\n            if not volume.empty:\n                volume.columns = tickers\n    close = close.dropna(axis=1, how="all").ffill().dropna(how="all")\n    volume = volume.reindex(index=close.index).dropna(axis=1, how="all") if not volume.empty else pd.DataFrame(index=close.index)\n    missing = [t for t in tickers if t not in close.columns]\n    return close, volume, missing\n\n@st.cache_data(ttl=3600, show_spinner=False)\ndef quote_metadata(tickers):\n    rows = []\n    for t in sorted(set(tickers)):\n        name, typ, group, link, country, region = asset_profile(t)\n        info_data = {}\n        try:\n            tk = yf.Ticker(t)\n            fi = {}\n            try:\n                fi = dict(tk.fast_info)\n            except Exception:\n                pass\n            info = {}\n            try:\n                info = tk.info or {}\n            except Exception:\n                pass\n            info_data = {\n                "currency": fi.get("currency") or info.get("currency"),\n                "market_cap": fi.get("market_cap") or info.get("marketCap"),\n                "shares": fi.get("shares") or info.get("sharesOutstanding"),\n                "avg_volume": fi.get("three_month_average_volume") or info.get("averageVolume") or info.get("averageVolume10days"),\n                "fifty_two_week_high": fi.get("year_high") or info.get("fiftyTwoWeekHigh"),\n                "fifty_two_week_low": fi.get("year_low") or info.get("fiftyTwoWeekLow"),\n                "sector": info.get("sector"),\n                "industry": info.get("industry"),\n                "beta_meta": info.get("beta"),\n                "enterprise_value": info.get("enterpriseValue"),\n            }\n        except Exception:\n            pass\n        rows.append({"ticker": t, "name": name, "type": typ, "group": group, "country": country, "region": region, "material/process link": link, **info_data})\n    return pd.DataFrame(rows)\n\n@st.cache_data(ttl=360, show_spinner=False)\ndef gdelt_news(query, n=60):\n    try:\n        r = requests.get(\n            "https://api.gdeltproject.org/api/v2/doc/doc",\n            params={"query": query, "mode": "ArtList", "format": "json", "maxrecords": n, "sort": "HybridRel"},\n            timeout=10,\n        )\n        if r.status_code != 200:\n            return pd.DataFrame()\n        return pd.DataFrame([{"title": a.get("title", ""), "source": a.get("domain", ""), "date": a.get("seendate", ""), "url": a.get("url", "")} for a in r.json().get("articles", [])])\n    except Exception:\n        return pd.DataFrame()\n\n@st.cache_data(ttl=900, show_spinner=False)\ndef google_news(query, n=50):\n    try:\n        url = "https://news.google.com/rss/search?q=" + quote_plus(query) + "&hl=en-US&gl=US&ceid=US:en"\n        r = requests.get(url, timeout=10, headers={"User-Agent": "MatQuantLab"})\n        if r.status_code != 200:\n            return pd.DataFrame()\n        root = ET.fromstring(r.content)\n        rows = []\n        for item in root.findall(".//item")[:n]:\n            rows.append({"title": (item.findtext("title") or "").strip(), "source": "Google News", "date": (item.findtext("pubDate") or "").strip(), "url": (item.findtext("link") or "").strip()})\n        return pd.DataFrame(rows)\n    except Exception:\n        return pd.DataFrame()\n\n# =============================================================================\n# ANALYTICS\n# =============================================================================\n\ndef market_tape(close, volume, tickers, meta, benchmark="SPY"):\n    rows = []\n    bench_ret = close[benchmark].pct_change() if benchmark in close.columns else None\n    bench_20 = None\n    if benchmark in close.columns and len(close[benchmark].dropna()) > 21:\n        b = close[benchmark].dropna()\n        bench_20 = float(b.iloc[-1] / b.iloc[-21] - 1)\n    for t in tickers:\n        if t not in close.columns:\n            continue\n        s = close[t].dropna()\n        if s.empty:\n            continue\n        r = s.pct_change()\n        v = volume[t].dropna() if t in volume.columns else pd.Series(dtype=float)\n        last = float(s.iloc[-1])\n        def ret(bars):\n            return np.nan if len(s) <= bars else float(s.iloc[-1] / s.iloc[-1-bars] - 1)\n        vol_last = float(v.iloc[-1]) if not v.empty else np.nan\n        dollar_vol = vol_last * last if pd.notna(vol_last) else np.nan\n        z = zscore(r, min(20, max(3, len(s)//4))).dropna()\n        zval = float(z.iloc[-1]) if not z.empty else np.nan\n        high = float(s.rolling(min(252, len(s))).max().iloc[-1])\n        low = float(s.rolling(min(252, len(s))).min().iloc[-1])\n        realized_vol = float(r.tail(60).std() * np.sqrt(252)) if len(s) > 65 else np.nan\n        beta_calc = np.nan\n        alpha20 = np.nan\n        if bench_ret is not None and t != benchmark:\n            joined = pd.concat([r.rename("r"), bench_ret.rename("b")], axis=1).dropna().tail(252)\n            if len(joined) > 30 and joined["b"].var() > 0:\n                beta_calc = float(joined["r"].cov(joined["b"]) / joined["b"].var())\n                if bench_20 is not None and len(s) > 21:\n                    alpha20 = ret(20) - beta_calc * bench_20\n        md = meta[meta["ticker"] == t]\n        md = md.iloc[0].to_dict() if not md.empty else {}\n        rows.append({\n            "ticker": t, "name": md.get("name", asset_profile(t)[0]), "type": md.get("type", asset_profile(t)[1]),\n            "last": last, "currency": md.get("currency",""), "volume": vol_last, "dollar volume": dollar_vol,\n            "avg volume": md.get("avg_volume", np.nan), "market value": md.get("market_cap", np.nan),\n            "enterprise value": md.get("enterprise_value", np.nan), "1 bar": ret(1), "5 bars": ret(5), "20 bars": ret(20),\n            "realized vol": realized_vol, "beta": beta_calc, "20-bar alpha": alpha20,\n            "52w high": md.get("fifty_two_week_high", high), "52w low": md.get("fifty_two_week_low", low),\n            "distance from 52w high": (last / md.get("fifty_two_week_high", high) - 1) if md.get("fifty_two_week_high", high) else np.nan,\n            "unusualness": zval,\n            "tape state": "stretched high" if zval > 1 else "stretched low" if zval < -1 else "balanced",\n            "sector": md.get("sector",""), "industry": md.get("industry",""),\n        })\n    return pd.DataFrame(rows)\n\ndef build_features(close, assets, shock_window):\n    n = len(close)\n    w = max(3, min(shock_window, max(3, n//5))) if n < 200 else max(5, min(shock_window, 100))\n    lag = max(1, min(w, max(1, n//4)))\n    feat = pd.DataFrame(index=close.index)\n    meta = []\n    for t in assets:\n        if t in close.columns:\n            c = f"asset:{t}"\n            feat[c] = zscore(close[t].pct_change(lag), w)\n            meta.append((c, t, "own recent move of selected instrument"))\n    chains = []\n    for t in assets:\n        chains += relevant_chains(t)\n    if not chains:\n        chains = list(CHAIN_MAP.keys())\n    for ch in sorted(set(chains)):\n        for proxy in CHAIN_MAP[ch]["proxy"]:\n            if proxy in close.columns:\n                c = f"chain:{ch}"\n                feat[c] = zscore(close[proxy].pct_change(lag), w)\n                meta.append((c, proxy, CHAIN_MAP[ch]["path"]))\n                break\n    for label, ticker in MACRO_PROXIES.items():\n        if ticker in close.columns:\n            c = f"macro:{label}"\n            feat[c] = zscore(close[ticker].pct_change(lag), w)\n            meta.append((c, ticker, "macro / cross-asset context"))\n    am_cols = [c for c in feat.columns if any(k in c for k in ["Titanium", "Nickel", "Aluminum", "Energy", "Steel", "powder"])]\n    if am_cols:\n        feat["basket:AM and powder metallurgy"] = feat[am_cols].mean(axis=1)\n    chain_cols = [c for c in feat.columns if c.startswith("chain:")]\n    feat["basket:material chain pressure"] = feat[chain_cols].mean(axis=1) if chain_cols else feat.mean(axis=1)\n    macro_cols = [c for c in feat.columns if c.startswith("macro:")]\n    feat["basket:macro pressure"] = feat[macro_cols].mean(axis=1) if macro_cols else pd.Series(0, index=feat.index)\n    feat = feat.replace([np.inf, -np.inf], np.nan).ffill().fillna(0)\n    return feat, pd.DataFrame(meta, columns=["feature", "source ticker", "meaning"]), w\n\ndef driver_table(features, focus):\n    latest = features.iloc[-1]\n    rows = []\n    for c, score in latest.items():\n        score = float(score)\n        if c.startswith("asset:"):\n            layer = "own tape"\n            plain = f"{readable_signal_name(c)} has moved unusually vs its recent range"\n        elif c.startswith("chain:"):\n            layer = "material chain"\n            plain = readable_signal_name(c)\n        elif c.startswith("macro:"):\n            layer = "macro"\n            plain = readable_signal_name(c)\n        elif c.startswith("basket:"):\n            layer = "basket"\n            plain = readable_signal_name(c)\n        else:\n            layer = "other"\n            plain = c\n        effect = effect_on_focus(c, score, focus)\n        rows.append({\n            "driver": c, "plain name": plain, "layer": layer, "reading": reading_label(score),\n            "score": score, "effect on focus": effect[0], "why it matters": effect[1],\n            "importance": abs(score),\n        })\n    return pd.DataFrame(rows).sort_values("importance", ascending=False)\n\ndef reading_label(score):\n    if score >= 1.5: return "very high vs recent history"\n    if score >= .75: return "high vs recent history"\n    if score <= -1.5: return "very low vs recent history"\n    if score <= -.75: return "low vs recent history"\n    return "near normal"\n\ndef effect_on_focus(feature, score, focus):\n    name, typ, group, link, country, region = asset_profile(focus)\n    text = f"{typ} {group} {link}".lower()\n    if feature.startswith("chain:"):\n        chain = feature.split(":",1)[1]\n        tilt, desc = chain_effect_for_focus(chain, score, focus)\n        return tilt, desc\n    if feature.startswith("macro:US 10Y") or feature.startswith("macro:US 13"):\n        return ("headwind" if score > .75 else "relief" if score < -.75 else "mixed",\n                "rates matter through discount rates and financing costs; small caps, growth, AM and cyclicals are usually more sensitive")\n    if feature.startswith("macro:US dollar"):\n        return ("headwind" if score > .75 else "tailwind" if score < -.75 else "mixed",\n                "a stronger dollar often pressures commodities and non-US earnings; a weaker dollar often helps commodity prices")\n    if feature.startswith("macro:VIX"):\n        return ("risk-off headwind" if score > .75 else "risk appetite support" if score < -.75 else "mixed",\n                "VIX is a risk-appetite gauge; high VIX usually pressures cyclical/high-beta instruments")\n    if feature.startswith("macro:WTI") or feature.startswith("macro:Natural gas") or "Energy" in feature:\n        return ("tailwind for energy, cost headwind for users" if score > .75 else "cost relief / weaker energy tape" if score < -.75 else "mixed",\n                "oil/gas affect fuel, logistics, smelting, heat treatment, atomization and chemical feedstocks")\n    if feature.startswith("asset:"):\n        return ("price momentum support" if score > .75 else "price momentum weakness" if score < -.75 else "balanced tape",\n                "this is the instrument\'s own price action, not a fundamental cause")\n    if "AM and powder" in feature:\n        return ("input-cost pressure for AM users" if score > .75 else "input relief for AM users" if score < -.75 else "mixed",\n                "captures metal powder, titanium/nickel/aluminum, process energy, HIP/LPBF/EBM-related pressure")\n    return ("mixed", "context signal; check the layer and the linked chart")\n\ndef transmission_map(assets, features):\n    latest = features.iloc[-1]\n    rows = []\n    for t in assets:\n        chains = relevant_chains(t)\n        cols = [f"chain:{c}" for c in chains if f"chain:{c}" in features.columns]\n        if "basket:AM and powder metallurgy" in features.columns and any(w in " ".join(asset_profile(t)).lower() for w in ["powder","additive","aerospace","titanium","hip","lpbf"]):\n            cols.append("basket:AM and powder metallurgy")\n        if not cols:\n            cols = ["basket:material chain pressure"] if "basket:material chain pressure" in features.columns else list(features.columns[:2])\n        score = float(latest[cols].mean()) if cols else 0\n        name, typ, group, link, country, region = asset_profile(t)\n        if score > .75:\n            state = "material/macro shock is close to this instrument"\n        elif score < -.75:\n            state = "linked inputs are easing around this instrument"\n        else:\n            state = "no strong chain pressure"\n        rows.append({\n            "ticker": t, "name": name, "type": typ, "group": group, "country": country, "region": region,\n            "mapped chains": ", ".join(chains) if chains else "broad macro / index",\n            "chain pressure": score, "plain reading": state,\n            "main path": " → ".join([readable_signal_name(x) for x in cols[:5]])\n        })\n    return pd.DataFrame(rows).sort_values("chain pressure", ascending=False)\n\n# =============================================================================\n# ML\n# =============================================================================\n\ndef model_set():\n    return {\n        "Ridge": Ridge(alpha=8),\n        "ElasticNet": ElasticNet(alpha=.01, l1_ratio=.2, random_state=42),\n        "Lasso": Lasso(alpha=.001, random_state=42),\n        "Huber": HuberRegressor(epsilon=1.35, alpha=.0001),\n        "RandomForest": RandomForestRegressor(n_estimators=120, max_depth=4, random_state=42, n_jobs=-1),\n        "ExtraTrees": ExtraTreesRegressor(n_estimators=170, max_depth=5, random_state=42, n_jobs=-1),\n        "GradientBoosting": GradientBoostingRegressor(max_depth=2, random_state=42),\n        "HistGradientBoosting": HistGradientBoostingRegressor(max_iter=120, max_leaf_nodes=15, random_state=42),\n        "Blended": VotingRegressor([\n            ("ridge", Ridge(alpha=8)),\n            ("trees", ExtraTreesRegressor(n_estimators=90, max_depth=4, random_state=42, n_jobs=-1)),\n            ("gb", GradientBoostingRegressor(max_depth=2, random_state=42)),\n        ]),\n    }\n\ndef fit_eval(model, Xtr, ytr, Xte, yte):\n    model.fit(Xtr, ytr)\n    pred = model.predict(Xte)\n    corr = pd.Series(pred).corr(pd.Series(yte.values))\n    corr = 0 if pd.isna(corr) else float(corr)\n    rmse = float(mean_squared_error(yte, pred) ** .5)\n    vol = max(float(ytr.std()), 1e-8)\n    score = corr - .10 * min(rmse / vol, 5)\n    return model, pred, corr, rmse, score\n\ndef importance(model, cols):\n    if hasattr(model, "feature_importances_"):\n        return pd.Series(model.feature_importances_, index=cols).sort_values(ascending=False)\n    if hasattr(model, "coef_"):\n        co = np.array(model.coef_).reshape(-1)\n        return pd.Series(np.abs(co), index=cols[:len(co)]).sort_values(ascending=False)\n    if hasattr(model, "estimators_"):\n        parts = []\n        for e in model.estimators_:\n            if hasattr(e, "feature_importances_"):\n                parts.append(pd.Series(e.feature_importances_, index=cols))\n            elif hasattr(e, "coef_"):\n                co = np.array(e.coef_).reshape(-1)\n                parts.append(pd.Series(np.abs(co), index=cols[:len(co)]))\n        if parts:\n            return pd.concat(parts, axis=1).mean(axis=1).sort_values(ascending=False)\n    return pd.Series(0, index=cols)\n\ndef final_verdict(direction, confidence, trust, corr, alpha20):\n    alpha_bonus = 0\n    if pd.notna(alpha20):\n        alpha_bonus = .15 if alpha20 > .02 else -.15 if alpha20 < -.02 else 0\n    strength = confidence + alpha_bonus\n    if direction == "upside" and trust in ["higher","medium"] and strength >= .55 and corr > .03:\n        return "BULLISH WATCH"\n    if direction == "downside" and trust in ["higher","medium"] and strength >= .55 and corr > .03:\n        return "BEARISH WATCH"\n    if direction == "upside" and strength >= .35:\n        return "SLIGHTLY BULLISH"\n    if direction == "downside" and strength >= .35:\n        return "SLIGHTLY BEARISH"\n    return "NEUTRAL / NO EDGE"\n\ndef train_signal(ticker, close, features, horizon, interval, model_choice, tape_df):\n    if ticker not in close.columns or len(close[ticker].dropna()) < 20:\n        return None, None\n    px = close[ticker].dropna()\n    h = max(1, min(int(horizon), max(1, min(len(px), len(features)) // 8)))\n    def dataset(hh):\n        y = close[ticker].pct_change(hh).shift(-hh).rename("future_return")\n        X = features.copy()\n        X = X.loc[:, X.std() > 1e-9]\n        return pd.concat([X, y], axis=1, join="inner").dropna(subset=["future_return"])\n    df = dataset(h)\n    if len(df) < 30:\n        h = max(1, min(5, horizon))\n        df = dataset(h)\n    if len(df) < 18:\n        h = 1\n        df = dataset(1)\n    if len(df) < 14:\n        return None, None\n    cols = [c for c in df.columns if c != "future_return"]\n    df[cols] = df[cols].fillna(0)\n    split = max(8, int(len(df)*.70))\n    if split >= len(df)-4:\n        split = max(6, len(df)-5)\n    tr, te = df.iloc[:split], df.iloc[split:]\n    if len(te) < 3:\n        return None, None\n    Xtr, ytr, Xte, yte = tr[cols], tr["future_return"], te[cols], te["future_return"]\n    models = model_set()\n    if model_choice == "Adaptive":\n        best = None\n        for nm, m in models.items():\n            try:\n                fm, p, corr, rmse, score = fit_eval(m, Xtr, ytr, Xte, yte)\n                if best is None or score > best["score"]:\n                    best = {"name": nm, "model": fm, "pred": p, "corr": corr, "rmse": rmse, "score": score}\n            except Exception:\n                pass\n        if best is None:\n            return None, None\n        model, pred, corr, rmse, model_name = best["model"], best["pred"], best["corr"], best["rmse"], best["name"]\n    else:\n        try:\n            model, pred, corr, rmse, _ = fit_eval(models[model_choice], Xtr, ytr, Xte, yte)\n            model_name = model_choice\n        except Exception:\n            return None, None\n    latest = float(model.predict(features.iloc[[-1]][cols].fillna(0))[0])\n    vol = max(float(ytr.std()), 1e-8)\n    confidence = min(abs(latest)/(vol*1.25), 1)\n    direction = "upside" if latest > 0 else "downside"\n    if len(te) < 8:\n        trust, reason = "low", "few validation observations"\n    elif corr > .12 and confidence > .50:\n        trust, reason = "higher", "validation was aligned with later returns"\n    elif corr > .03 and confidence > .33:\n        trust, reason = "medium", "validation was positive but not strong"\n    elif corr > 0:\n        trust, reason = "low-medium", "validation was weak but positive"\n    else:\n        trust, reason = "low", "validation did not support the direction"\n    imp = importance(model, cols)\n    drivers = list(imp.index[:3])\n    try:\n        until = pd.Timestamp(px.index[-1]) + delta_for(interval, h)\n        until_s = str(until)[:16]\n    except Exception:\n        until_s = "next horizon window"\n    trw = tape_df[tape_df["ticker"] == ticker]\n    alpha20 = trw["20-bar alpha"].iloc[0] if not trw.empty and "20-bar alpha" in trw else np.nan\n    beta = trw["beta"].iloc[0] if not trw.empty and "beta" in trw else np.nan\n    verdict = final_verdict(direction, confidence, trust, corr, alpha20)\n    invalid = "; ".join([f"{readable_signal_name(d)} returns to normal or flips direction" for d in drivers[:2]]) if drivers else "top drivers reverse"\n    message = f"{ticker}: {verdict}. Model points {direction} over {h} {interval} bars. Trust is {trust} because {reason}. Useful until about {until_s}, or earlier if {invalid}."\n    curve = te.copy()\n    curve["prediction"] = pred\n    curve["future_return"] = yte\n    curve["diagnostic_curve"] = (1 + np.sign(curve["prediction"]) * curve["future_return"].fillna(0)).cumprod()\n    return {\n        "ticker": ticker, "final verdict": verdict, "direction": direction, "trust": trust, "model": model_name,\n        "predicted return": latest, "confidence": confidence, "test corr": corr, "rmse": rmse,\n        "beta": beta, "20-bar alpha": alpha20, "horizon bars": h, "valid until": until_s,\n        "driver 1": drivers[0] if len(drivers)>0 else "", "driver 2": drivers[1] if len(drivers)>1 else "", "driver 3": drivers[2] if len(drivers)>2 else "",\n        "message": message\n    }, curve\n\n# =============================================================================\n# NEWS AND SCENARIOS\n# =============================================================================\n\ndef news_query(base_terms, assets):\n    terms = list(base_terms)\n    for a in assets:\n        name, typ, group, link, country, region = asset_profile(a)\n        terms += [a, name, typ, group, link, country, region]\n        for ch in relevant_chains(a):\n            terms += CHAIN_MAP[ch]["keywords"] + [ch]\n    clean, seen = [], set()\n    for t in terms:\n        for p in str(t).replace("/", " ").split(","):\n            p = p.strip()\n            if p and p.lower() not in seen and len(p) < 80:\n                clean.append(p); seen.add(p.lower())\n    return "(" + " OR ".join(clean[:80]) + ")"\n\ndef news_themes(news):\n    themes = {\n        "energy / fuel": ["oil","gas","lng","fuel","opec","refinery","hormuz"],\n        "critical minerals": ["critical minerals","rare earth","lithium","cobalt","nickel","graphite","titanium"],\n        "AM / powder metallurgy": ["powder metallurgy","additive manufacturing","3d printing","metal powder","lpbf","ebm","hip"],\n        "aerospace / defense": ["aerospace","defense","missile","aircraft","procurement","backlog"],\n        "China / controls": ["china","taiwan","export control","sanction","tariff"],\n        "gold / silver": ["gold","silver","bullion","safe haven"],\n    }\n    if news.empty:\n        return 0.0, pd.DataFrame({"theme": list(themes.keys()), "mentions": 0})\n    txt = " ".join(news["title"].fillna("").str.lower().tolist())\n    rows, score = [], 0\n    for th, words in themes.items():\n        cnt = sum(txt.count(w) for w in words)\n        rows.append({"theme": th, "mentions": cnt})\n        score += cnt\n    return min(score/10, 4.0), pd.DataFrame(rows).sort_values("mentions", ascending=False)\n\ndef scenario_effect_for_asset(ticker, shocks):\n    name, typ, group, link, country, region = asset_profile(ticker)\n    text = f"{ticker} {name} {typ} {group} {link} {country} {region}".lower()\n    score, reasons = 0.0, []\n    def add(key, cond, producer_cond=None, user_mult=-0.5, producer_mult=0.7):\n        nonlocal score, reasons\n        if any(w in text for w in cond):\n            producer = producer_cond and any(w in text for w in producer_cond)\n            mult = producer_mult if producer else user_mult\n            val = shocks.get(key,0) * mult\n            score += val\n            if abs(val) > 0:\n                reasons.append(f"{SCENARIO_LABELS[key]} {\'helps\' if val>0 else \'hurts\'}")\n    add("copper", ["copper","electrification","grid"], ["miner","mining","copper"], -.55, .85)\n    add("aluminum", ["aluminum","aerospace","auto","packaging"], ["aluminum","smelting"], -.55, .75)\n    add("titanium", ["titanium","aerospace","engine"], ["specialty alloys"], -.55, .75)\n    add("nickel", ["nickel","superalloy","engine","battery"], ["nickel","mining"], -.55, .8)\n    add("steel", ["steel","machinery","auto","construction","powder metallurgy"], ["steel"], -.5, .7)\n    add("battery", ["battery","ev","lithium","cobalt","graphite"], ["lithium","battery materials"], -.45, .75)\n    add("rare_earth", ["rare","magnet","defense","semiconductor"], ["rare earth"], -.45, .8)\n    add("uranium", ["uranium","nuclear"], ["uranium"], -.2, .9)\n    add("precious", ["gold","silver","safe"], ["gold","silver"], .2, .8)\n    add("energy", ["oil","gas","fuel","smelting","chemicals","power","aerospace","europe"], ["energy","oil","gas"], -.65, .8)\n    add("defense", ["defense","missile","procurement"], ["defense"], .7, .7)\n    add("aerospace", ["aerospace","aircraft","engine"], ["aerospace"], .65, .65)\n    add("semis", ["semiconductor","electronics","chip"], ["semiconductor"], .65, .65)\n    add("ampm", ["powder","additive","lpbf","ebm","hip","titanium"], ["additive"], -.5, .55)\n    add("freight", ["transport","logistics","autos","aerospace","industrial","europe"], ["shipping"], -.4, .5)\n    add("policy", ["rare","defense","china","battery","semiconductor","titanium"], ["mining"], -.45, .5)\n    # broad macro overlays\n    score += shocks.get("usd",0)*(-.35)\n    score += shocks.get("rates",0)*(-.35)\n    score += shocks.get("vix",0)*(-.6)\n    score += shocks.get("credit",0)*(-.45)\n    score += shocks.get("china",0)*(0.55 if any(w in text for w in ["china","mining","copper","steel","auto","battery"]) else 0.15)\n    score += shocks.get("eu",0)*(0.55 if any(w in text for w in ["europe","germany","france","italy","united kingdom","autos","aerospace"]) or ticker in ["VGK","^STOXX50E","^GDAXI","^FCHI","^FTSE"] else 0.05)\n    if shocks.get("usd",0): reasons.append("USD overlay")\n    if shocks.get("rates",0): reasons.append("rates overlay")\n    if shocks.get("vix",0): reasons.append("risk-off overlay")\n    if shocks.get("credit",0): reasons.append("credit overlay")\n    if shocks.get("china",0): reasons.append("China demand overlay")\n    if shocks.get("eu",0): reasons.append("Europe demand overlay")\n    reading = "TAILWIND" if score > .5 else "HEADWIND" if score < -.5 else "MIXED"\n    return score, reading, ", ".join(reasons[:5]) or "mostly broad macro beta"\n\ndef scenario_table(assets, shocks):\n    rows = []\n    for a in assets:\n        score, reading, reason = scenario_effect_for_asset(a, shocks)\n        rows.append({"ticker": a, "scenario score": score, "scenario reading": reading, "why": reason})\n    return pd.DataFrame(rows).sort_values("scenario score", ascending=False)\n\n# =============================================================================\n# PLOTS\n# =============================================================================\n\ndef line_chart(df, title, yaxis="value", normalize=False):\n    if df.empty:\n        st.info("No data for this chart.")\n        return\n    x = df.copy().dropna(how="all").ffill()\n    if normalize and len(x):\n        x = x / x.iloc[0]\n    fig = go.Figure()\n    for c in x.columns:\n        fig.add_trace(go.Scatter(x=x.index, y=x[c], name=str(c), mode="lines", hovertemplate=f"{c}<br>%{{x}}<br>%{{y:.4f}}<extra></extra>"))\n    fig.update_layout(title=title, height=410, xaxis_title="time", yaxis_title=yaxis, hovermode="x unified", margin=dict(l=20,r=20,t=55,b=30))\n    st.plotly_chart(fig, use_container_width=True)\n\ndef bar_chart(df, x, y, title):\n    if df.empty:\n        st.info("No data for this chart.")\n        return\n    d = df.copy().sort_values(x)\n    fig = go.Figure(go.Bar(x=d[x], y=d[y], orientation="h", text=[f"{v:.2f}" for v in d[x]], textposition="auto"))\n    fig.update_layout(title=title, height=max(330, min(850, 28*len(d)+80)), xaxis_title=x, yaxis_title="", margin=dict(l=20,r=20,t=55,b=30))\n    st.plotly_chart(fig, use_container_width=True)\n\n# =============================================================================\n# APP\n# =============================================================================\n\nst.set_page_config(page_title="MatQuantLab", layout="wide")\nst.title("MatQuantLab")\nst.subheader("Clear instrument cockpit: tape → drivers → chain → verdict")\nst.caption("Designed to avoid vague scores: every signal is translated into what happened, why it matters, and what it means for the selected instrument.")\n\nwith st.sidebar:\n    st.header("Research setup")\n    universe = st.radio("Universe", ["Core ETFs/assets","Manufacturing companies","Commodities/futures","Major indices","Everything"], index=4)\n    regions = st.multiselect("Region filter", sorted(COMPANIES["region"].dropna().unique().tolist()) if not COMPANIES.empty else [], default=[])\n    countries = st.multiselect("Country filter", sorted(COMPANIES["country"].dropna().unique().tolist()) if not COMPANIES.empty else [], default=[])\n    core = sorted(CORE_ASSETS.keys())\n    comp_df = COMPANIES.copy()\n    if regions: comp_df = comp_df[comp_df["region"].isin(regions)]\n    if countries: comp_df = comp_df[comp_df["country"].isin(countries)]\n    comp = sorted(comp_df["ticker"].astype(str).tolist())\n    fut = sorted(set(FUTURES.values()))\n    idx = sorted(set(MAJOR_INDICES.values()))\n    if universe == "Core ETFs/assets": choices = core\n    elif universe == "Manufacturing companies": choices = comp\n    elif universe == "Commodities/futures": choices = fut\n    elif universe == "Major indices": choices = idx\n    else: choices = sorted(set(core + comp + fut + idx))\n    default_assets = [x for x in ["SPY","IWM","VGK","COPX","XME","PRNT","GLD","USO","URA","REMX","^RUT"] if x in choices]\n    assets = st.multiselect("Instruments to analyze", choices, default=default_assets[:10])\n    focus = st.selectbox("Focus instrument", assets if assets else ["SPY"])\n    benchmark = st.selectbox("Benchmark for alpha/beta", ["SPY","IWM","RSP","^GSPC","^RUT"], index=0)\n    interval = st.selectbox("Data interval", ["1m","5m","15m","30m","60m","1d"], index=5)\n    period = st.selectbox("History", ["1d","5d","1mo","3mo","6mo","1y","2y","5y","10y"], index=7)\n    model_choice = st.selectbox("ML model", ["Adaptive","Ridge","ElasticNet","Lasso","Huber","RandomForest","ExtraTrees","GradientBoosting","HistGradientBoosting","Blended"], index=0)\n    horizon = st.slider("Research horizon, bars", 1, 120, 10)\n    shock_window = st.slider("Unusualness window, bars", 3, 150, 20)\n    fast = st.toggle("Fast mode", value=True)\n    st.markdown("**News terms**")\n    base_terms = st.multiselect("Base terms", sorted(["critical minerals","rare earth","export controls","sanctions","Iran","Strait of Hormuz","Red Sea","oil","gas","LNG","gold","silver","China","Taiwan","titanium powder","powder metallurgy","LPBF","EBM","HIP","aerospace backlog","defense procurement","Russell 2000","small caps","credit spread","rates"]), default=["critical minerals","rare earth","export controls","oil","gas","gold","China","powder metallurgy"])\n    extra_terms = st.text_input("Extra event terms, comma separated", value="")\n    if extra_terms:\n        base_terms += [x.strip() for x in extra_terms.split(",") if x.strip()]\n    auto = st.toggle("Auto-refresh", value=False)\n    refresh_seconds = st.selectbox("Refresh every", [30,60,120,300], index=1)\n    if st.button("Refresh now"):\n        st.cache_data.clear(); st.rerun()\n\nif auto:\n    time.sleep(refresh_seconds); st.cache_data.clear(); st.rerun()\n\nif not assets:\n    st.warning("Select at least one instrument.")\n    st.stop()\n\nactual_period = compatible_period(interval, period)\nchains = []\nfor a in assets:\n    chains += relevant_chains(a)\nproxy_tickers = []\nfor ch in sorted(set(chains)):\n    proxy_tickers += CHAIN_MAP[ch]["proxy"][:2 if fast else 3]\nessential = list(MACRO_PROXIES.values())[:10] + [benchmark, "SPY","IWM","RSP","VGK","^RUT","^GSPC","DX-Y.NYB","^VIX","GC=F","CL=F","NG=F","HG=F","SI=F"]\ndownload_list = sorted(set(assets + proxy_tickers + essential + ([] if fast else list(FUTURES.values()) + list(MAJOR_INDICES.values()))))\n\nclose, volume, missing = download_ohlcv(download_list, actual_period, interval)\nif close.empty:\n    st.error("No market data loaded. Try daily interval, fewer instruments, or core assets.")\n    st.stop()\n\navailable_assets = [a for a in assets if a in close.columns]\nmeta = quote_metadata(available_assets + [focus, benchmark])\ntape = market_tape(close, volume, available_assets, meta, benchmark=benchmark if benchmark in close.columns else "SPY")\nfeatures, feature_meta, used_window = build_features(close, available_assets, shock_window)\ndrivers = driver_table(features, focus)\ntransmission = transmission_map(available_assets, features)\n\nsig_rows, curves = [], {}\nfor a in available_assets:\n    row, curve = train_signal(a, close, features, horizon, interval, model_choice, tape)\n    if row:\n        name, typ, group, link, country, region = asset_profile(a)\n        row.update({"name":name, "type":typ, "group":group, "country":country, "region":region, "material/process link":link})\n        sig_rows.append(row); curves[a] = curve\nsignals = pd.DataFrame(sig_rows)\nif not signals.empty:\n    order = {"higher":0,"medium":1,"low-medium":2,"low":3}\n    signals["_o"] = signals["trust"].map(order).fillna(9)\n    signals = signals.sort_values(["_o","confidence"], ascending=[True,False]).drop(columns="_o")\n\nquery = news_query(base_terms, available_assets)\nnews = pd.concat([gdelt_news(query, 60), google_news(query, 50)], ignore_index=True)\nevent_score, theme_table = news_themes(news)\n\nfocus_tape = tape[tape["ticker"] == focus]\nfocus_signal = signals[signals["ticker"] == focus] if not signals.empty and focus in signals["ticker"].values else pd.DataFrame()\nlast = focus_tape["last"].iloc[0] if not focus_tape.empty else np.nan\nvol = focus_tape["volume"].iloc[0] if not focus_tape.empty and "volume" in focus_tape else np.nan\nmc = focus_tape["market value"].iloc[0] if not focus_tape.empty and "market value" in focus_tape else np.nan\nverdict = focus_signal.iloc[0]["final verdict"] if not focus_signal.empty else "n/a"\n\nk1,k2,k3,k4,k5,k6,k7 = st.columns(7)\nk1.metric("Focus", focus)\nk2.metric("Last price", fmt_num(last))\nk3.metric("Volume", fmt_num(vol))\nk4.metric("Market value", fmt_num(mc))\nk5.metric("Verdict", verdict)\nk6.metric("Event risk", f"{event_score:.2f}")\nk7.metric("Data used", actual_period)\n\nif actual_period != period:\n    st.warning(f"{interval} data cannot support {period} well; this run uses {actual_period}.")\nif missing:\n    with st.expander("Unavailable tickers", expanded=False):\n        st.write(", ".join(missing[:120]))\n\ntabs = st.tabs(["Read Me First", "Market Tape", "Driver Explanation", "Material Chain", "ML Verdict", "Scenario Lab", "News", "Data Quality"])\n\nwith tabs[0]:\n    st.subheader("Read me first")\n    st.markdown(APP_PURPOSE)\n    name, typ, group, link, country, region = asset_profile(focus)\n    st.markdown("### Focus instrument")\n    c1,c2,c3,c4 = st.columns(4)\n    c1.metric("Name", name[:32])\n    c2.metric("Type", typ)\n    c3.metric("Country", country or "n/a")\n    c4.metric("Group", group[:28])\n    st.write(f"**Material/process link:** {link}")\n    st.markdown("### Plain-English conclusion")\n    if not focus_signal.empty:\n        st.info(focus_signal.iloc[0]["message"])\n    else:\n        st.info(f"{focus}: no stable ML verdict. Use tape + drivers + scenario lab; do not force a model conclusion.")\n    st.markdown("### Top things that changed")\n    top = drivers.head(6)[["plain name","layer","reading","effect on focus","why it matters","score"]]\n    st.dataframe(top, use_container_width=True, hide_index=True)\n\nwith tabs[1]:\n    st.subheader("Market tape")\n    st.caption("This is actual trading data: price, volume, market value, returns, volatility, alpha and beta.")\n    show = tape.copy()\n    for c in ["last","volume","dollar volume","avg volume","market value","enterprise value","52w high","52w low"]:\n        if c in show: show[c] = show[c].apply(fmt_num)\n    for c in ["1 bar","5 bars","20 bars","realized vol","20-bar alpha","distance from 52w high"]:\n        if c in show: show[c] = show[c].apply(fmt_pct)\n    for c in ["beta","unusualness"]:\n        if c in show: show[c] = show[c].apply(lambda x: "" if pd.isna(x) else f"{x:.2f}")\n    st.dataframe(show, use_container_width=True, hide_index=True)\n    mode = st.radio("Chart mode", ["Focus raw price", "Selected raw prices", "Selected indexed", "Returns"], horizontal=True)\n    if mode == "Focus raw price":\n        cols = [focus] if focus in close.columns else []\n        for ch in relevant_chains(focus):\n            for t in CHAIN_MAP[ch]["proxy"][:1]:\n                if t in close.columns: cols.append(t)\n        line_chart(close[list(dict.fromkeys(cols))], f"{focus}: actual price and relevant proxies", "actual price")\n    elif mode == "Selected raw prices":\n        line_chart(close[[a for a in available_assets if a in close.columns][:12]], "Selected instruments — actual prices", "actual price")\n    elif mode == "Selected indexed":\n        line_chart(close[[a for a in available_assets if a in close.columns][:14]], "Selected instruments — indexed to 1.0", "indexed", normalize=True)\n    else:\n        ret = close[[a for a in available_assets if a in close.columns][:14]].pct_change().fillna(0).cumsum()\n        line_chart(ret, "Selected instruments — cumulative return proxy", "return proxy")\n\nwith tabs[2]:\n    st.subheader("Driver explanation")\n    st.markdown("No more vague \'upward pressure\'. This table tells you **what moved, whether it is unusual, and why it helps or hurts the focus instrument**.")\n    show = drivers.head(18)[["plain name","layer","reading","effect on focus","why it matters","score"]]\n    st.dataframe(show, use_container_width=True, hide_index=True)\n    for _, r in drivers.head(8).iterrows():\n        st.write(f"• **{r[\'plain name\']}** — {r[\'reading\']} → **{r[\'effect on focus\']}**. {r[\'why it matters\']}")\n    split = st.radio("Show driver chart", ["Only macro", "Only material chains", "Only own tape", "All"], horizontal=True)\n    d = drivers.copy()\n    if split == "Only macro": d = d[d["layer"] == "macro"]\n    elif split == "Only material chains": d = d[d["layer"] == "material chain"]\n    elif split == "Only own tape": d = d[d["layer"] == "own tape"]\n    bar_chart(d.head(20), "score", "plain name", f"{split} drivers")\n\nwith tabs[3]:\n    st.subheader("Material chain")\n    st.markdown("This is the chain of connection: physical input → industrial process → selected instrument.")\n    st.dataframe(transmission, use_container_width=True, hide_index=True)\n    if len(transmission) > 1:\n        bar_chart(transmission, "chain pressure", "ticker", "Chain pressure by instrument")\n    else:\n        st.info("Only one instrument selected. The table is more useful than a one-bar chart.")\n    st.markdown("### Focus chain details")\n    chains_focus = relevant_chains(focus)\n    if not chains_focus:\n        st.info("No specific material chain mapped. This instrument is mainly macro/index driven.")\n    for ch in chains_focus:\n        spec = CHAIN_MAP[ch]\n        with st.expander(ch, expanded=True):\n            st.write(f"**Path:** {spec[\'path\']}")\n            st.write(f"**If you are a producer:** {spec[\'producer_effect\']}")\n            st.write(f"**If you are a user/manufacturer:** {spec[\'user_effect\']}")\n            loaded = [p for p in spec["proxy"] if p in close.columns]\n            if loaded:\n                line_chart(close[loaded], f"{ch}: actual proxy prices", "actual price")\n\nwith tabs[4]:\n    st.subheader("ML verdict")\n    st.caption("Verdicts are research labels, not investment advice. They need direction + validation + confidence.")\n    if signals.empty:\n        st.warning("No ML verdicts. Try daily data, longer history, fewer instruments.")\n    else:\n        show = signals[["ticker","name","type","group","final verdict","direction","trust","model","predicted return","confidence","test corr","beta","20-bar alpha","driver 1","driver 2","driver 3","horizon bars","valid until","message"]].copy()\n        for c in ["predicted return","20-bar alpha"]:\n            show[c] = show[c].apply(fmt_pct)\n        for c in ["confidence","test corr","beta"]:\n            show[c] = show[c].apply(lambda x: "" if pd.isna(x) else f"{x:.3f}")\n        st.dataframe(show, use_container_width=True, hide_index=True)\n        inspect = st.selectbox("Inspect verdict", signals["ticker"].tolist(), index=signals["ticker"].tolist().index(focus) if focus in signals["ticker"].tolist() else 0)\n        r = signals[signals["ticker"] == inspect].iloc[0]\n        c1,c2,c3,c4 = st.columns(4)\n        c1.metric("Verdict", r["final verdict"])\n        c2.metric("Trust", r["trust"])\n        c3.metric("Predicted return", fmt_pct(r["predicted return"]))\n        c4.metric("Valid until", r["valid until"])\n        st.write(r["message"])\n        if inspect in curves:\n            line_chart(curves[inspect][["prediction","future_return"]], f"{inspect}: prediction vs later return", "return")\n            st.caption("If prediction and later return disagree often, reduce trust.")\n            line_chart(curves[inspect][["diagnostic_curve"]], f"{inspect}: diagnostic curve", "index")\n\nwith tabs[5]:\n    st.subheader("Scenario lab")\n    st.markdown("Use presets first. Sliders are shock assumptions: **+ means the shock rises**, **- means it eases or weakens**.")\n    preset = st.selectbox("Scenario preset", list(SCENARIO_PRESETS.keys()), index=0)\n    shocks = {k: SCENARIO_PRESETS[preset].get(k, 0.0) for k in SCENARIO_LABELS}\n    st.markdown("### Shock assumptions")\n    cols = st.columns(4)\n    for i, k in enumerate(SCENARIO_LABELS):\n        with cols[i % 4]:\n            shocks[k] = st.slider(SCENARIO_LABELS[k], -2.0, 2.0, float(shocks.get(k,0.0)), .25)\n    active = {k:v for k,v in shocks.items() if abs(v) > 0}\n    if not active:\n        st.info("No scenario shock selected. Choose a preset or move sliders. A zero-shock scenario correctly has no message.")\n    else:\n        st.write("Active shocks: " + ", ".join([f"{SCENARIO_LABELS[k]}={v:+.2f}" for k,v in active.items()]))\n        scen = scenario_table(available_assets, shocks)\n        st.dataframe(scen, use_container_width=True, hide_index=True)\n        if len(scen) > 1:\n            bar_chart(scen, "scenario score", "ticker", "Scenario impact by instrument")\n        else:\n            st.info("Only one instrument selected. The scenario reading is in the table above.")\n        st.markdown("**How to read this:** Tailwind means the mapped exposure benefits from the assumed shock. Headwind means the mapped exposure is hurt. This is exposure logic, not ML prediction.")\n\nwith tabs[6]:\n    st.subheader("News")\n    st.code(query)\n    n1,n2,n3 = st.columns(3)\n    n1.metric("Event risk", f"{event_score:.2f}")\n    n2.metric("Headlines", len(news))\n    n3.metric("Query terms", len(query.split(" OR ")))\n    st.dataframe(theme_table, use_container_width=True, hide_index=True)\n    if not theme_table.empty:\n        bar_chart(theme_table.rename(columns={"mentions":"score","theme":"plain name"}), "score", "plain name", "News theme intensity")\n    if news.empty:\n        st.info("No news returned. Use fewer or broader terms.")\n    else:\n        st.dataframe(news[["title","source","date","url"]].head(150), use_container_width=True, hide_index=True)\n\nwith tabs[7]:\n    st.subheader("Data quality")\n    q1,q2,q3,q4 = st.columns(4)\n    q1.metric("Requested history", period)\n    q2.metric("Actual history", actual_period)\n    q3.metric("Price rows", len(close))\n    q4.metric("Feature rows", len(features))\n    st.write(f"Price coverage: `{close.index[0]}` → `{close.index[-1]}`")\n    st.write(f"Unusualness window used: `{used_window}`")\n    st.markdown("### Downloaded close prices")\n    st.dataframe(close.tail(120), use_container_width=True)\n    st.markdown("### Downloaded volumes")\n    st.dataframe(volume.tail(120), use_container_width=True)\n    st.markdown("### Feature metadata")\n    st.dataframe(feature_meta, use_container_width=True, hide_index=True)\n    st.markdown("### Company universe")\n    st.dataframe(COMPANIES, use_container_width=True, hide_index=True)\n\nst.divider()\nst.caption("Research cockpit. Free market/news data may be delayed or unavailable. Verdicts are diagnostics, not financial advice.")\n')
